import itertools
def get_girth(adj, n):
    min_g = n + 1
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        parent = [-1] * n
        q = [start]
        i = 0
        while i < len(q):
            u = q[i]
            i += 1
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_g:
                        min_g = cycle_len
    return min_g
